func testConhecimentoTransportesUpdate(t *testing.T) {
	t.Parallel()

	if 0 == len(conhecimentoTransportePrimaryKeyColumns) {
		t.Skip("Skipping table with no primary key columns")
	}
	if len(conhecimentoTransporteAllColumns) == len(conhecimentoTransportePrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &ConhecimentoTransporte{}
	if err = randomize.Struct(seed, o, conhecimentoTransporteDBTypes, true, conhecimentoTransporteColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize ConhecimentoTransporte struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := ConhecimentoTransportes().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, conhecimentoTransporteDBTypes, true, conhecimentoTransportePrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize ConhecimentoTransporte struct: %s", err)
	}

	if rowsAff, err := o.Update(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("should only affect one row but affected", rowsAff)
	}
}

